import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarSaudador, criarContadorRapido } from './solution.mjs';

test('método com function comum usa o this do objeto', () => {
  const pessoa = criarSaudador('Maria');
  assert.equal(pessoa.saudar(), 'Olá, eu sou Maria!');
});

test('arrow no topo do módulo não tem this próprio', () => {
  const pessoa = criarSaudador('Maria');
  assert.throws(() => pessoa.saudarArrow());
});

test('arrow dentro de método comum herda o this do método', () => {
  const contador = criarContadorRapido();
  contador.incrementarDepois();
  assert.equal(contador.valor, 2);
});

solutionCode:
export function criarSaudador(nome) {
  return {
    nome,
    saudar: function () {
      return `Olá, eu sou ${this.nome}!`;
    },
    saudarArrow: () => `Olá, eu sou ${this.nome}!`,
  };
}

export function criarContadorRapido() {
  return {
    valor: 0,
    incrementarDepois: function () {
      const incrementar = () => {
        this.valor += 1;
      };
      incrementar();
      incrementar();
    },
  };
}
